select pg_temp.claim(3);
select pg_temp.ok((select count(*)=0 from public.lesson_segments where lesson_id=current_setting('lessons.lesson')::uuid),'other tenant owner cannot read parts');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'create_module',null,null,null,'{"title":"Intrusion"}')$s$,'42501','other tenant owner cannot edit');
select pg_temp.claim(7);
select pg_temp.ok((select count(*)=0 from public.lessons where id=current_setting('lessons.lesson')::uuid),'unenrolled student cannot read lesson');
select pg_temp.denied($s$select public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,10,false,0)$s$,'42501','unenrolled progress denied');
