select pg_temp.ok((select count(*)=1 from public.lesson_segments where lesson_id=current_setting('lessons.lesson')::uuid),'student only sees published part');
select pg_temp.denied($s$insert into public.lesson_segments(lesson_id,title,position) values(current_setting('lessons.lesson')::uuid,'Forged',10)$s$,'42501','direct student part creation denied');
