select pg_temp.denied($s$select public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,20,true,0)$s$,'PT409','stale progress rejected');
select pg_temp.ok((public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,20,true,1)->>'status')='completed','part completes');
