select pg_temp.denied($s$select public.save_segment_progress('60000000-0000-0000-0000-000000000001',current_setting('lessons.part')::uuid,10,false,0)$s$,'42501','same student cannot mix offering courses');
select pg_temp.denied($s$update public.lesson_segment_progress set status='completed'$s$,'42501','direct progress mutation denied');
select pg_temp.claim(6);
select pg_temp.ok((select count(*)=0 from public.lesson_segment_progress where lesson_id=current_setting('lessons.lesson')::uuid),'other student cannot read progress');
select pg_temp.ok((public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,2,false,0)->>'revision')::int=1,'independent student progress');
select pg_temp.claim(2);
select pg_temp.ok((select count(*)=2 from public.lesson_segment_progress where lesson_id=current_setting('lessons.lesson')::uuid),'assigned teacher sees offering progress');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'reorder_segments',null,current_setting('lessons.lesson')::uuid,null,
 jsonb_build_object('items',(select jsonb_agg(jsonb_build_object('id',id,'updated_at',updated_at) order by position desc) from public.lesson_segments where lesson_id=current_setting('lessons.lesson')::uuid)));
select pg_temp.ok((select position=1 from public.lesson_segments where id=current_setting('lessons.part')::uuid),'atomic reorder swaps unique positions');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'reorder_segments',null,current_setting('lessons.lesson')::uuid,null,'{"items":[]}')$s$,'PT409','incomplete reorder rejected');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,'2000-01-01','{"title":"Stale","status":"draft"}')$s$,'PT409','stale teacher edit rejected');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,(select updated_at from public.lesson_segments where id=current_setting('lessons.part')::uuid),'{"title":"Part A","description":"Notes","status":"draft"}');
select pg_temp.claim(5);
select pg_temp.ok((select count(*)=0 from public.lesson_segments where id=current_setting('lessons.part')::uuid),'unpublish immediately hides direct row');
select pg_temp.denied($s$select public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,30,false,3)$s$,'42501','unpublish blocks further progress');
set local role anon;
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'create_module',null,null,null,'{"title":"No"}')$s$,'42501','anonymous author RPC denied');
select pg_temp.denied($s$select public.save_segment_progress(current_setting('lessons.offering')::uuid,current_setting('lessons.part')::uuid,0,false,0)$s$,'42501','anonymous progress RPC denied');
