select set_config('lessons.asset',gen_random_uuid()::text,true);
insert into public.media_assets(id,organization_id,uploaded_by,kind,mime_type,original_filename,bucket,object_path,status)
values(current_setting('lessons.asset')::uuid,'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','pdf','application/pdf','Synthetic notes.pdf','lms-course-media','20000000-0000-0000-0000-000000000001/'||current_setting('lessons.asset')||'/notes.pdf','ready');
