select pg_temp.ok((select count(*)=3 and bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('lesson_segments','lesson_resources','lesson_segment_progress')),'all three new tables have RLS');
